public static class FormatDate
{
    public static bool FormatDate(string text, string query)
    {
        return text.Contains(query.ToLower());
    }
}

solutionCode:
public static class FormatDate
{
    public static bool FormatDate(string text, string query)
    {
        return text.ToLower().Contains(query.ToLower());
    }
}
